const ONI_BUILDINGS_BY_ANIMATION: Record<string, OniBuildingDefinition> = Object.fromEntries(
  Object.values(ONI_BUILDING_DEFINITIONS).map((definition) => [definition.animation.replace(/_kanim$/i, '').toLowerCase(), definition]),
)

export function oniBuildingDefinitionForTag(tag: string): OniBuildingDefinition | undefined {
  return ONI_BUILDING_DEFINITIONS[tag.trim().toLowerCase()]
}

export function oniBuildingDefinitionForAnimation(animation: string): OniBuildingDefinition | undefined {
  return ONI_BUILDINGS_BY_ANIMATION[animation.trim().replace(/_kanim$/i, '').toLowerCase()]
}
